// Parse, validate, and de-duplicate raw sensor readings.
// Output 1 = clean reading, Output 2 = dropped reading (for the debug sidebar).
let data;
try {
    data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    return [null, { payload: { reason: "invalid_json", raw: msg.payload } }];
}

if (!data || !data.nodeId || !data.region || !data.readings) {
    return [null, { payload: { reason: "missing_fields", data } }];
}

// Physically valid range per sensor. Anything outside = dropout/stuck/spike fault.
const ranges = {
    temperature: [-10, 80],
    humidity: [0, 100],
    windSpeed: [0, 150],
    smokeLevel: [0, 2000],
};
for (const k of Object.keys(ranges)) {
    const [lo, hi] = ranges[k];
    const v = data.readings[k];
    if (typeof v !== "number" || !isFinite(v) || v < lo || v > hi) {
        return [null, { payload: { reason: "invalid_" + k, value: v, nodeId: data.nodeId } }];
    }
}

// De-duplicate exact re-deliveries (same node + timestamp) seen in the last 60s.
const seen = flow.get("seen") || {};
const key = data.nodeId + "|" + data.timestamp;
const now = Date.now();
if (seen[key]) {
    return [null, { payload: { reason: "duplicate", key } }];
}
seen[key] = now;
for (const k of Object.keys(seen)) {
    if (now - seen[k] > 60000) delete seen[k];
}
flow.set("seen", seen);

msg.payload = data;
return [msg, null];

// Standardise structure and timestamp before forwarding to the cloud services.
const d = msg.payload;
msg.payload = {
    nodeId: d.nodeId,
    region: d.region,
    timestamp: d.timestamp ? new Date(d.timestamp).toISOString() : new Date().toISOString(),
    location: d.location || null,
    readings: {
        temperature: d.readings.temperature,
        humidity: d.readings.humidity,
        windSpeed: d.readings.windSpeed,
        smokeLevel: d.readings.smokeLevel,
    },
};

// REST token auth: attach a bearer token to the ingestion/detection calls when
// AUTH_ENABLED=true. The header flows on to http_detect via fn_route as well.
const headers = { "Content-Type": "application/json" };
if (String(env.get("AUTH_ENABLED") || "").toLowerCase() === "true" && env.get("API_TOKEN")) {
    headers["Authorization"] = "Bearer " + env.get("API_TOKEN");
}
msg.headers = headers;
return msg;

// Route risky readings (elevated smoke) to the detection service as well.
// Every reading still goes to ingestion; only these also go to /api/detect.
const SMOKE_ELEVATED = 150; // ppm  (keep in sync with detection SMOKE_ELEVATED_PPM)
if ((msg.payload.readings.smokeLevel || 0) >= SMOKE_ELEVATED) {
    return msg;
}
return null;
